    C c;
    constructor(C _c) { c = _c; }

    // run performs either Put via explicit call or via fallback by sending 0 unlockTime
    // params: amount to send to Put/fallback, unlockTime to pass to Put, and a flag useFallback
    function run(uint amount, uint unlockTime, bool useFallback) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund call");

        // read pre-state: recorded balance for this contract and contract's ETH balance
        uint beforeRecorded = c.Acc(address(this)).balance;
        uint beforeCbal = address(c).balance;

        bool reverted;
        if (useFallback) {
            // send Ether to fallback which calls Put(0)
            try c.f{value: amount}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call Put directly with provided unlockTime
            try c.Put{value: amount}(unlockTime) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // read post-state
        uint afterRecorded = c.Acc(address(this)).balance;
        uint afterCbal = address(c).balance;

        // If call reverted, recorded balance and contract balance must be unchanged.
        // If call succeeded, the recorded balance must have increased by exactly amount
        // and contract's ETH balance must have increased by at least amount.
        assert(
            (reverted && afterRecorded == beforeRecorded && afterCbal == beforeCbal)
            || (!reverted && afterRecorded == beforeRecorded + amount && afterCbal >= beforeCbal + amount)
        );
    }

    // Allow receiving ETH so tests can fund this contract
    receive() external payable {}
}

