contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to withdraw _am after optionally setting an unlockTime and funding the contract with Put.
    // amountPut is Ether to send when calling Put (may be 0). We always ensure this test contract has funds.
    function run(uint amountPut, uint putUnlockTime, uint collectAmount, bool doPut) public payable {
        require(address(this).balance >= amountPut, "insufficient balance to fund Put");

        // Observe recorded balance before any operations
        (uint beforeUnlock, uint beforeRecorded) = c.Acc(address(this));

        // Optionally fund via Put (state-changing call must be top-level)
        if (doPut) {
            c.Put{value: amountPut}(putUnlockTime);
        }

        // Observe recorded balance immediately before attempting Collect
        (uint midUnlock, uint midRecorded) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Observe recorded balance after Collect
        (uint afterUnlock, uint afterRecorded) = c.Acc(address(this));

        // General invariant:
        // Collect must never increase the stored recorded balance for this test contract.
        // I.e., afterRecorded <= midRecorded always holds.
        // Additionally, if Collect succeeded (did not revert) then either
        //   - midRecorded was < MinSum, or midRecorded < collectAmount, or block.timestamp <= unlockTime (so Collect's if-condition failed and nothing happened), in which case recorded balance stays the same;
        //   - or Collect's conditions held and the recorded balance decreased by exactly collectAmount.
        // We express a single assert that enforces the essential part: no increase, and if not reverted and decreased then decrease equals collectAmount.
        bool decreasedCorrectly = (!collectReverted && midRecorded >= collectAmount && afterRecorded + collectAmount == midRecorded) || (collectReverted == true) || (afterRecorded == midRecorded);

        assert(afterRecorded <= midRecorded && decreasedCorrectly);
    }

    // accept Ether so this contract can be funded externally for tests
    receive() external payable {}
}

