    // We take parameters: unlockTime for Put, and amount of wei to send when calling Put.
    // This test will call Put with value `amount` and then assert that the observable
    // Acc(this).balance and contract balance reflect a non-decreasing change equal to the sent amount when call succeeds.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-values from the public surface
        C.Holder memory before = c.Acc(address(this));
        uint beforeHolderBalance = before.balance;
        uint beforeContractBal = address(c).balance;

        // Perform the call, capturing whether it reverted
        bool reverted;
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        C.Holder memory after = c.Acc(address(this));
        uint afterHolderBalance = after.balance;
        uint afterContractBal = address(c).balance;

        // Assert general invariant:
        // If Put succeeded, then the holder's public balance must have increased by exactly `amount` (or at least not decreased),
        // and the contract's balance must have increased by exactly `amount` as well.
        // If Put reverted, balances must be unchanged.
        assert(
            reverted
            ? (afterHolderBalance == beforeHolderBalance && afterContractBal == beforeContractBal)
            : (afterHolderBalance >= beforeHolderBalance && afterContractBal >= beforeContractBal && (afterHolderBalance - beforeHolderBalance) == (afterContractBal - beforeContractBal) && (afterHolderBalance - beforeHolderBalance) == amount)
        );
    }

    // Allow receiving refunds or sent Ether if needed
    receive() external payable {}
}

