contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test Collect behavior: take an amount to attempt to collect.
    // This function sends no Ether to c; it only calls Collect(am).
    function run(uint am) public payable {
        // No precondition on am (can be zero).

        // Read before-values via public getter
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Call Collect and record whether it reverted
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If the call reverted -> balances and unlock unchanged.
        // If it succeeded -> both the public holder balance and contract balance
        // either both decreased by exactly am, or both remained unchanged (Collect may no-op when preconditions not met).
        // Additionally, unlockTime must not increase as a result of Collect (Collect only decreases balance and doesn't touch unlockTime in success path),
        // so afterUnlock <= beforeUnlock.
        assert(
            reverted
            ? (afterBalance == beforeBalance && afterContractBal == beforeContractBal && afterUnlock == beforeUnlock)
            : (
                // succeeded: either exact decrease by am on both observables, or no change
                (
                    afterBalance == beforeBalance && afterContractBal == beforeContractBal
                ) || (
                    // avoid underflow in the assert by using comparisons
                    beforeBalance >= am && beforeContractBal >= am
                    && afterBalance == beforeBalance - am
                    && afterContractBal == beforeContractBal - am
                )
            )
            && afterUnlock <= beforeUnlock
        );
    }

    receive() external payable {}
}

