contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run simulates: caller (this test) puts some Ether, then attempts to collect _am.
    // Params:
    //  putAmt - amount of wei to deposit via Put (sent with call)
    //  unlockOffset - amount added to block.timestamp to set unlockTime in Put (if zero, Put sets unlockTime to block.timestamp)
    //  am - amount to attempt to Collect
    function run(uint putAmt, uint unlockOffset, uint am) public payable {
        require(address(this).balance >= putAmt, "need funds to Put");

        // record contract balance before any operations
        uint beforeContractBal = address(c).balance;

        // perform Put with value putAmt, setting unlock time to block.timestamp + unlockOffset
        // ensure we call with value by using low-level check
        if (putAmt > 0) {
            // send Ether to c.Put
            c.Put{value: putAmt}(block.timestamp + unlockOffset);
        } else {
            // call without value
            c.Put(block.timestamp + unlockOffset);
        }

        // read the published Holder struct via public getter: Acc(address)
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // record contract balance after Put
        uint midContractBal = address(c).balance;

        // attempt Collect and catch whether it reverts
        bool reverted;
        // we must call Collect as a top-level statement; use try/catch on external call
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read Holder after Collect attempt
        (uint finalUnlockTime, uint finalBalance) = c.Acc(address(this));

        uint afterContractBal = address(c).balance;

        // If Collect succeeded (did not revert) then the following must hold:
        // 1) finalBalance = afterBalance - am
        // 2) contract's balance decreased by at least am (it may decrease more if other side effects occur, but should not increase)
        // We express "decreased by at least am" as: midContractBal - afterContractBal >= am when Collect succeeded.

        assert(reverted || (
            // ensure no underflow in expression by using comparisons
            afterBalance >= am && finalBalance + am == afterBalance && midContractBal >= afterContractBal && (midContractBal - afterContractBal) >= am
        ));
    }

    // Allow contract to receive Ether so Put can be funded by this test when deployed with value
    receive() external payable {}
}
